-- 00. 1단계 적용 전 점검 (조회 전용, 데이터·설정 변경 없음)
-- 결과 표 전체를 캡처해 보내 주세요. ok 가 false 인 행이 있으면 적용하지 않습니다.
-- expected 가 '기록용'인 행은 되돌리기 SQL이 원래 상태와 맞는지 확인하는 데 씁니다.
SELECT no, item, actual, expected,
       CASE WHEN expected = '기록용' THEN NULL ELSE actual IS NOT DISTINCT FROM expected END AS ok
FROM (VALUES
    (1, '090000 함수 audit_log_row_change 본문 md5', (SELECT md5(replace(prosrc, chr(13), '')) FROM pg_proc WHERE oid = to_regprocedure('public.audit_log_row_change()')), 'c0bd7152725a93208d5b4f8ced2092be'),
    (2, '090000 함수 audit_logs_chain_hash 본문 md5', (SELECT md5(replace(prosrc, chr(13), '')) FROM pg_proc WHERE oid = to_regprocedure('public.audit_logs_chain_hash()')), '60aa255d13c4007fb8f581e63c3088db'),
    (3, '090000 함수 block_append_only_change 본문 md5', (SELECT md5(replace(prosrc, chr(13), '')) FROM pg_proc WHERE oid = to_regprocedure('public.block_append_only_change()')), 'f76cf4c5ad38d2f311d82e3d04b24259'),
    (4, '090000 함수 purge_old_access_and_audit_logs 본문 md5', (SELECT md5(replace(prosrc, chr(13), '')) FROM pg_proc WHERE oid = to_regprocedure('public.purge_old_access_and_audit_logs()')), '7bc4a70f737b0710ac9dc15732fe1b2f'),
    (5, '090000 감사로그 기록 함수가 로그인 없는 변경도 기록', (SELECT (prosrc LIKE '%direct_sql%')::text FROM pg_proc WHERE oid = to_regprocedure('public.audit_log_row_change()')), 'true'),
    (6, '090000 로그 삭제 함수가 감사로그를 지우지 않음', (SELECT (prosrc NOT LIKE '%audit_logs%')::text FROM pg_proc WHERE oid = to_regprocedure('public.purge_old_access_and_audit_logs()')), 'true'),
    (7, '090000 audit_logs 추가 컬럼 10개', (SELECT count(*)::text FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'audit_logs' AND column_name IN ('actor_source','db_session_user','db_role_setting','jwt_role','application_name','txid','correction_id','chain_seq','prev_hash','row_hash')), '10'),
    (8, '090000 data_corrections 테이블', (to_regclass('public.data_corrections') IS NOT NULL)::text, 'true'),
    (9, '090000 audit_logs 트리거(해시 체인·추가 전용·TRUNCATE 차단)', (SELECT count(*)::text FROM pg_trigger WHERE tgrelid = 'public.audit_logs'::regclass AND tgname IN ('trg_audit_logs_chain_hash','trg_audit_logs_append_only','trg_audit_logs_no_truncate')), '3'),
    (10, '090000 data_corrections 추가 전용 트리거', (SELECT count(*)::text FROM pg_trigger WHERE tgrelid = to_regclass('public.data_corrections') AND tgname IN ('trg_data_corrections_append_only','trg_data_corrections_no_truncate')), '2'),
    (11, '090000 감사 트리거 부착 테이블 수(일지 25 + 생산 3)', (SELECT count(*)::text FROM pg_trigger t JOIN pg_class c ON c.oid = t.tgrelid WHERE t.tgname = 'trg_audit_row_change' AND c.relnamespace = 'public'::regnamespace), '28'),
    (12, '로그 정리 예약 작업(pg_cron) 활성', (SELECT count(*)::text FROM cron.job WHERE command ILIKE '%purge_old_access_and_audit_logs%' AND active), '1'),
    (13, '[093000 전] 로그 삭제 함수 실행 권한 anon/authenticated/service_role', (SELECT concat_ws('/', has_function_privilege('anon', 'public.purge_old_access_and_audit_logs()', 'EXECUTE'), has_function_privilege('authenticated', 'public.purge_old_access_and_audit_logs()', 'EXECUTE'), has_function_privilege('service_role', 'public.purge_old_access_and_audit_logs()', 'EXECUTE'))), '기록용'),
    (14, '[093000 전] 로그 삭제 함수 ACL', (SELECT CASE WHEN proacl IS NULL THEN '(기본값)' ELSE (SELECT string_agg(a::text, ',' ORDER BY a::text) FROM unnest(proacl) a) END FROM pg_proc WHERE oid = to_regprocedure('public.purge_old_access_and_audit_logs()')), '기록용'),
    (15, '[093000 전] audit_logs INSERT 권한 anon/authenticated/service_role', concat_ws('/', has_table_privilege('anon', 'public.audit_logs', 'INSERT'), has_table_privilege('authenticated', 'public.audit_logs', 'INSERT'), has_table_privilege('service_role', 'public.audit_logs', 'INSERT')), '기록용'),
    (16, '[093000 전] audit_logs 정책', (SELECT string_agg(policyname || ' ' || cmd || ' ' || roles::text || ' ' || COALESCE(with_check, qual, ''), ' ; ' ORDER BY policyname) FROM pg_policies WHERE schemaname = 'public' AND tablename = 'audit_logs'), '기록용'),
    (17, '[095000 전] 일지 25개 테이블 존재', (SELECT count(*)::text FROM unnest(ARRAY['daily_hygiene_logs', 'daily_temp_humidity_logs', 'daily_sanitation_facility_logs', 'daily_worker_hygiene_logs', 'daily_cold_storage_hygiene_logs', 'daily_process_control_bread_logs', 'daily_material_storage_3f_logs', 'daily_manufacturing_equipment_logs', 'daily_air_conditioning_equipment_logs', 'daily_hoist_inspection_logs', 'daily_illumination_logs', 'daily_material_receiving_inspection_logs', 'daily_raw_thawing_logs', 'daily_hygiene_log_items', 'daily_temp_humidity_log_items', 'daily_sanitation_facility_log_items', 'daily_worker_hygiene_log_items', 'daily_cold_storage_hygiene_log_items', 'daily_process_control_bread_log_items', 'daily_material_storage_3f_log_items', 'daily_manufacturing_equipment_log_items', 'daily_air_conditioning_equipment_log_items', 'daily_hoist_inspection_log_items', 'daily_illumination_log_items', 'daily_material_receiving_inspection_log_items']::text[]) t WHERE to_regclass('public.' || t) IS NOT NULL), '25'),
    (18, '[095000 전] 일지 정책 수(25개 × 4종)', (SELECT count(*)::text FROM pg_policies WHERE schemaname = 'public' AND tablename = ANY (ARRAY['daily_hygiene_logs', 'daily_temp_humidity_logs', 'daily_sanitation_facility_logs', 'daily_worker_hygiene_logs', 'daily_cold_storage_hygiene_logs', 'daily_process_control_bread_logs', 'daily_material_storage_3f_logs', 'daily_manufacturing_equipment_logs', 'daily_air_conditioning_equipment_logs', 'daily_hoist_inspection_logs', 'daily_illumination_logs', 'daily_material_receiving_inspection_logs', 'daily_raw_thawing_logs', 'daily_hygiene_log_items', 'daily_temp_humidity_log_items', 'daily_sanitation_facility_log_items', 'daily_worker_hygiene_log_items', 'daily_cold_storage_hygiene_log_items', 'daily_process_control_bread_log_items', 'daily_material_storage_3f_log_items', 'daily_manufacturing_equipment_log_items', 'daily_air_conditioning_equipment_log_items', 'daily_hoist_inspection_log_items', 'daily_illumination_log_items', 'daily_material_receiving_inspection_log_items']::text[])), '100'),
    (19, '[095000 전] 그중 역할 지정 없는 USING(true) 기존 정책', (SELECT count(*)::text FROM pg_policies WHERE schemaname = 'public' AND tablename = ANY (ARRAY['daily_hygiene_logs', 'daily_temp_humidity_logs', 'daily_sanitation_facility_logs', 'daily_worker_hygiene_logs', 'daily_cold_storage_hygiene_logs', 'daily_process_control_bread_logs', 'daily_material_storage_3f_logs', 'daily_manufacturing_equipment_logs', 'daily_air_conditioning_equipment_logs', 'daily_hoist_inspection_logs', 'daily_illumination_logs', 'daily_material_receiving_inspection_logs', 'daily_raw_thawing_logs', 'daily_hygiene_log_items', 'daily_temp_humidity_log_items', 'daily_sanitation_facility_log_items', 'daily_worker_hygiene_log_items', 'daily_cold_storage_hygiene_log_items', 'daily_process_control_bread_log_items', 'daily_material_storage_3f_log_items', 'daily_manufacturing_equipment_log_items', 'daily_air_conditioning_equipment_log_items', 'daily_hoist_inspection_log_items', 'daily_illumination_log_items', 'daily_material_receiving_inspection_log_items']::text[]) AND policyname IN (tablename || '_select', tablename || '_insert', tablename || '_update', tablename || '_delete') AND roles::text = '{public}' AND COALESCE(qual, 'true') = 'true' AND COALESCE(with_check, 'true') = 'true'), '100'),
    (20, '[095000 전] 예상 밖 정책(있으면 095000 이 스스로 중단)', (SELECT count(*)::text FROM pg_policies WHERE schemaname = 'public' AND tablename = ANY (ARRAY['daily_hygiene_logs', 'daily_temp_humidity_logs', 'daily_sanitation_facility_logs', 'daily_worker_hygiene_logs', 'daily_cold_storage_hygiene_logs', 'daily_process_control_bread_logs', 'daily_material_storage_3f_logs', 'daily_manufacturing_equipment_logs', 'daily_air_conditioning_equipment_logs', 'daily_hoist_inspection_logs', 'daily_illumination_logs', 'daily_material_receiving_inspection_logs', 'daily_raw_thawing_logs', 'daily_hygiene_log_items', 'daily_temp_humidity_log_items', 'daily_sanitation_facility_log_items', 'daily_worker_hygiene_log_items', 'daily_cold_storage_hygiene_log_items', 'daily_process_control_bread_log_items', 'daily_material_storage_3f_log_items', 'daily_manufacturing_equipment_log_items', 'daily_air_conditioning_equipment_log_items', 'daily_hoist_inspection_log_items', 'daily_illumination_log_items', 'daily_material_receiving_inspection_log_items']::text[]) AND policyname NOT IN (tablename || '_select', tablename || '_insert', tablename || '_update', tablename || '_delete', tablename || '_org_access')), '0'),
    (21, '[095000 전] RLS 켜진 일지 테이블', (SELECT count(*)::text FROM pg_class WHERE oid = ANY (SELECT to_regclass('public.' || t) FROM unnest(ARRAY['daily_hygiene_logs', 'daily_temp_humidity_logs', 'daily_sanitation_facility_logs', 'daily_worker_hygiene_logs', 'daily_cold_storage_hygiene_logs', 'daily_process_control_bread_logs', 'daily_material_storage_3f_logs', 'daily_manufacturing_equipment_logs', 'daily_air_conditioning_equipment_logs', 'daily_hoist_inspection_logs', 'daily_illumination_logs', 'daily_material_receiving_inspection_logs', 'daily_raw_thawing_logs', 'daily_hygiene_log_items', 'daily_temp_humidity_log_items', 'daily_sanitation_facility_log_items', 'daily_worker_hygiene_log_items', 'daily_cold_storage_hygiene_log_items', 'daily_process_control_bread_log_items', 'daily_material_storage_3f_log_items', 'daily_manufacturing_equipment_log_items', 'daily_air_conditioning_equipment_log_items', 'daily_hoist_inspection_log_items', 'daily_illumination_log_items', 'daily_material_receiving_inspection_log_items']::text[]) t) AND relrowsecurity), '기록용'),
    (22, '[095000 전] anon 이 조회·추가·수정·삭제 모두 가능한 일지 테이블', (SELECT count(*)::text FROM unnest(ARRAY['daily_hygiene_logs', 'daily_temp_humidity_logs', 'daily_sanitation_facility_logs', 'daily_worker_hygiene_logs', 'daily_cold_storage_hygiene_logs', 'daily_process_control_bread_logs', 'daily_material_storage_3f_logs', 'daily_manufacturing_equipment_logs', 'daily_air_conditioning_equipment_logs', 'daily_hoist_inspection_logs', 'daily_illumination_logs', 'daily_material_receiving_inspection_logs', 'daily_raw_thawing_logs', 'daily_hygiene_log_items', 'daily_temp_humidity_log_items', 'daily_sanitation_facility_log_items', 'daily_worker_hygiene_log_items', 'daily_cold_storage_hygiene_log_items', 'daily_process_control_bread_log_items', 'daily_material_storage_3f_log_items', 'daily_manufacturing_equipment_log_items', 'daily_air_conditioning_equipment_log_items', 'daily_hoist_inspection_log_items', 'daily_illumination_log_items', 'daily_material_receiving_inspection_log_items']::text[]) t WHERE has_table_privilege('anon', 'public.' || t, 'SELECT') AND has_table_privilege('anon', 'public.' || t, 'INSERT') AND has_table_privilege('anon', 'public.' || t, 'UPDATE') AND has_table_privilege('anon', 'public.' || t, 'DELETE')), '기록용'),
    (23, '[095000 전] daily_log_org_codes 함수(아직 없어야 함)', (to_regprocedure('public.daily_log_org_codes()') IS NOT NULL)::text, 'false'),
    (24, 'SQL Editor 실행 역할 / RLS 우회 / 일지 테이블 소유자', (SELECT current_user || ' / ' || rolbypassrls::text || ' / ' || (SELECT pg_get_userbyid(relowner) FROM pg_class WHERE oid = 'public.daily_hygiene_logs'::regclass) FROM pg_roles WHERE rolname = current_user), '기록용')
) AS v(no, item, actual, expected)
ORDER BY no;
